contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            depositsAfter == depositsBefore &&
            (
                (reverted && balAfter == balBefore) ||
                (!reverted && balAfter + amount == balBefore)
            )
        );
    }

    receive() external payable {}
}

